/**
 * Obfuskuje email (svaki znak -> HTML hex entitet) da ga spam-harvesteri teže pokupe,
 * a browser ga i dalje ispravno prikaže/otvori. Koristi se u mailto href-u i tekstu.
 */
if (!function_exists('vug_email_obf')) {
    function vug_email_obf(string $email): string {
        $out = '';
        foreach (str_split($email) as $ch) {
            $out .= '&#' . ord($ch) . ';';
        }
        return $out;
    }
}

