if (!function_exists('vug_icon')) {
    /**
     * Vraća inline <svg> ikonicu koja referencira sprite (#vi-<name>).
     * @param string $name  Ime ikonice (npr. 'arrow-right').
     * @param string $class Dodatne CSS klase.
     * @param bool   $label Ako je true, ikonica NIJE aria-hidden (nosi značenje).
     */
    function vug_icon(string $name, string $class = '', bool $label = false): string {
        $name = preg_replace('/^bi-/', '', $name); // toleriši i "bi-foo" i "foo"
        $cls = trim('vi bi bi-' . $name . ($class !== '' ? ' ' . $class : ''));
        $a11y = $label ? 'role="img"' : 'aria-hidden="true"';
        return '<svg class="' . htmlspecialchars($cls, ENT_QUOTES) . '" ' . $a11y
             . ' width="1em" height="1em" fill="currentColor"><use href="#vi-'
             . htmlspecialchars($name, ENT_QUOTES) . '"></use></svg>';
    }
}

if (!function_exists('vug_icon_sprite')) {
    /** Vraća skriveni SVG sprite sa svim <symbol> definicijama (ubaciti jednom u <body>). */
    function vug_icon_sprite(): string {
        $s = '<svg xmlns="http://www.w3.org/2000/svg" style="position:absolute;width:0;height:0;overflow:hidden" aria-hidden="true" focusable="false">';
        foreach ($GLOBALS['VUG_ICONS'] as $name => $inner) {
            $s .= '<symbol id="vi-' . $name . '" viewBox="0 0 16 16">' . $inner . '</symbol>';
        }
        $s .= '</svg>';
        return $s;
    }
}